ALTER TABLE reg_registration_submission ADD COLUMN nation varchar(20);
UPDATE reg_registration_submission SET nation = CASE nation_id WHEN 1 THEN 'England' WHEN 2 THEN 'Scotland' WHEN 3 THEN 'Wales' WHEN 4 THEN 'NorthernIreland' END;
ALTER TABLE reg_registration_submission ALTER COLUMN nation SET NOT NULL, ADD CONSTRAINT ck_reg_registration_submission_nation CHECK (nation IN ('England', 'Scotland', 'Wales', 'NorthernIreland')), DROP COLUMN nation_id;
